import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { useSelfServiceEmployee } from '@/features/selfServices/context/SelfServiceEmployeeContext';

export default function ServicesEmployeePicker() {
    const {
        isPrivileged,
        employeeOptions,
        selectedEmployeeId,
        setSelectedEmployeeId,
        needsEmployeeSelection,
    } = useSelfServiceEmployee();

    if (!isPrivileged) {
        return null;
    }

    return (
        <div className="mb-6 flex flex-col gap-2 max-w-md">
            <label className="text-sm font-semibold text-[#080614]">عرض بيانات الموظف</label>
            <Select
                value={selectedEmployeeId != null ? String(selectedEmployeeId) : ''}
                onValueChange={(v) => setSelectedEmployeeId(v ? parseInt(v, 10) : null)}
            >
                <SelectTrigger className="w-full bg-white">
                    <SelectValue placeholder="اختر الموظف" />
                </SelectTrigger>
                <SelectContent>
                    {employeeOptions.map((e) => (
                        <SelectItem key={e.id} value={String(e.id)}>
                            {e.name}
                        </SelectItem>
                    ))}
                </SelectContent>
            </Select>
            {needsEmployeeSelection && (
                <p className="text-sm text-amber-800">اختر موظفاً لعرض الطلبات والتقارير الخاصة به.</p>
            )}
        </div>
    );
}
